package com.termux.app.workspace;
import java.util.*;
import java.util.function.LongSupplier;
/** Bounded metadata-only timings. No prompts, paths, file contents or generated text. */
final class LocalAiTiming {
 final LongSupplier clock;long started,stageAt,first=-1,ended;String phase="idle",model="",backend="";int context,answer,prompt=-1,tokens=-1;boolean active;volatile boolean paused;long genFirst=-1,genAt,genDuration;int genCalls;int processed=-1,total=-1,cached=-1;long prefillMs=-1,cacheMs=-1,firstStepMs=-1,setupMs=-1;String cacheStatus="";
 org.json.JSONObject inputBudget;
 final ArrayList<String> events=new ArrayList<>();
 final ArrayList<String[]> passes=new ArrayList<>();boolean passClosed;int omittedPasses;
 private String passReport(boolean ru,String state,long now){
  StringBuilder s=new StringBuilder(ru?"Проход ":"Pass ").append(genCalls).append(" · ").append(state).append("\n");
  s.append(ru?"Вход / обработано / из кэша / пересчитать (токены): ":"Input / processed / cached / to evaluate (tokens): ").append(total<0?"—":total).append(" / ").append(processed<0?"—":processed).append(" / ").append(cached<0?"—":cached).append(" / ").append(total<0||cached<0?"—":total-cached).append("\n");
  s.append(ru?"Кэш: ":"Cache: ").append(cacheStatus.isEmpty()?"—":cacheStatus).append("\n");
  s.append(ru?"Вход / кэш / подготовка / первый токен (мс): ":"Input / cache / setup / first token (ms): ").append(prefillMs<0?"—":prefillMs).append(" / ").append(cacheMs<0?"—":cacheMs).append(" / ").append(setupMs<0?"—":setupMs).append(" / ").append(firstStepMs<0?"—":firstStepMs).append("\n");
  s.append(ru?"До первого текста / генерация (мс): ":"Until first text / generation (ms): ").append(genFirst<0?"—":Math.max(0,genFirst-genAt)).append(" / ").append(genFirst<0?"—":(genDuration>0?genDuration:Math.max(0,now-genFirst))).append("\n");
  s.append(LocalAiInputBudget.report(inputBudget,ru));s.append(ru?"Выход (токены): ":"Output (tokens): ").append(tokens<0?"—":tokens).append("\n");return s.toString();
 }
 private void closePass(boolean completed){if(genCalls==0||passClosed)return;passClosed=true;if(paused)return;long now=clock.getAsLong();passes.add(new String[]{passReport(true,completed?"завершён":"не завершён",now),passReport(false,completed?"completed":"not completed",now)});if(passes.size()>64){passes.remove(0);omittedPasses++;}}
 private String passesReport(boolean ru){StringBuilder s=new StringBuilder(ru?"\nОбращения к модели:\n":"\nModel calls:\n");for(String[] p:passes)s.append(p[ru?0:1]).append("\n");if(genCalls>0&&!passClosed)s.append(passReport(ru,ru?"в процессе":"in progress",clock.getAsLong())).append("\n");if(omittedPasses>0)s.append(ru?"Старых проходов удалено: ":"Older passes omitted: ").append(omittedPasses).append("\n");return s.toString();}

 LocalAiTiming(){this(android.os.SystemClock::elapsedRealtime);}LocalAiTiming(LongSupplier clock){this.clock=clock;}
 synchronized void begin(WorkspaceStore.Session p,String engine){model=p.localModel;backend=engine;context=p.localContext;answer=p.localMaxTokens;started=stageAt=clock.getAsLong();first=-1;ended=0;genAt=genDuration=0;genFirst=-1;genCalls=0;prompt=tokens=-1;processed=total=cached=-1;prefillMs=cacheMs=firstStepMs=setupMs=-1;cacheStatus="";active=true;phase="preparation";inputBudget=null;events.clear();passes.clear();passClosed=false;omittedPasses=0;}
 synchronized void phase(String next){if(!active||next.equals(phase))return;long now=clock.getAsLong();if(!paused){events.add(phase+": "+(now-stageAt)+" ms");if(events.size()>160)events.remove(0);}stageAt=now;phase=next;if(next.equals("postprocessing"))closePass(true);if(next.equals("context_preparation")){closePass(false);passClosed=false;inputBudget=null;genCalls++;genAt=now;genFirst=-1;genDuration=0;prompt=tokens=-1;processed=total=cached=-1;prefillMs=cacheMs=firstStepMs=setupMs=-1;cacheStatus="";}}
 synchronized void text(String value){if(value.isEmpty()||!active)return;if(first<0)first=clock.getAsLong();if(genFirst<0)genFirst=clock.getAsLong();if(phase.equals("first_token")||phase.equals("prefill")||phase.equals("context_preparation")||phase.equals("generating"))phase("generation");}
 synchronized void metrics(int input,int output){prompt=input;tokens=output;genDuration=Math.max(0,clock.getAsLong()-(genFirst<0?genAt:genFirst));}
 synchronized void finish(String state){if(!active)return;closePass(false);phase(state);ended=clock.getAsLong();active=false;}
 synchronized void performance(String json){if(!active)return;try{org.json.JSONObject p=new org.json.JSONObject(json);if(p.optString("kind").equals("input_breakdown")){if(p.optBoolean("unavailable")){inputBudget=p;return;}int n=p.getInt("total");if(n<0)return;long sum=0;for(String key:new String[]{"system","history","tools","current","format"}){int value=p.getInt(key);if(Math.abs((long)value)>10000000)return;sum+=value;}if(sum==n)inputBudget=p;return;}int n=p.getInt("total"),done=p.getInt("processed"),reuse=p.getInt("cached");long pre=p.getLong("prefillMs"),cache=p.getLong("cacheMs"),step=p.getLong("firstTokenMs"),setup=p.optLong("setupMs",0);if(n<1||done<0||done>n||reuse<0||reuse>done||pre<0||cache<0||step< -1||setup<0)return;total=n;processed=done;cached=reuse;prefillMs=pre;cacheMs=cache;firstStepMs=step;setupMs=setup;String state=p.optString("cacheStatus");cacheStatus=state.matches("[a-z_]{1,40}")?state:"";}catch(Exception ignored){}}

 static String label(String value,boolean ru){switch(value){case "idle":return ru?"Запрос ещё не запущен":"No request started";case "preparation":case "context_preparation":return ru?"Подготовка контекста":"Preparing context";case "context_shortening":return ru?"Сокращение контекста":"Shortening context";case "prefill":return ru?"Обработка входных токенов":"Processing input tokens";case "first_token":return ru?"Первый шаг генерации":"First generation step";case "generating":return ru?"Ожидание первого текста модели":"Waiting for first model text";case "postprocessing":return ru?"Подготовка результата":"Preparing result";case "generation":return ru?"Генерация ответа":"Generating response";case "running:list":case "running:search":case "running:screenshots":return ru?"Поиск файла":"Finding files";case "running:read":return ru?"Чтение файла":"Reading file";case "running:locations":return ru?"Проверка папок":"Checking folders";case "file_choice":return ru?"Ожидание выбора файла":"Waiting for file selection";case "tool_validation":return ru?"Исправление параметров инструмента":"Correcting tool arguments";case "approval":return ru?"Ожидание разрешения":"Waiting for approval";case "finished":return ru?"Завершено":"Finished";case "error":return ru?"Ошибка или остановлено":"Error or stopped";default:return ru?"Выполнение инструмента":"Running tool";}}
 synchronized String eventsReport(boolean ru){StringBuilder text=new StringBuilder();for(String e:events){int at=e.lastIndexOf(": ");text.append(label(at<0?e:e.substring(0,at),ru)).append(at<0?"":e.substring(at)).append("\n");}return text.length()==0?(ru?"Событий пока нет":"No events yet"):text.toString();}
 synchronized String report(boolean ru){long now=active?clock.getAsLong():ended;StringBuilder s=new StringBuilder("Termux Job’s "+com.termux.BuildConfig.VERSION_NAME+" · Local AI\n");s.append(ru?"Модель: ":"Model: ").append(model).append("\n").append(ru?"Движок / ускорение: ":"Engine / acceleration: ").append(backend).append("\n").append(ru?"Контекст / максимум ответа: ":"Context / max reply: ").append(context).append(" / ").append(answer).append("\n").append(ru?"Этап: ":"Stage: ").append(label(phase,ru));if(active)s.append(" · ").append(Math.max(0,now-stageAt)).append(" ms");s.append("\n").append(ru?"Общее время: ":"Total time: ").append(started==0&&ended==0&&!active?0:Math.max(0,now-started)).append(" ms\n");s.append(ru?"До первого текста модели: ":"Until first model text: ").append(first<0?(ru?"нет данных":"unavailable"):(first-started)+" ms").append("\n");s.append(ru?"Обработка входа: ":"Input processing: ").append(processed<0?"—":processed+" / "+total).append("\n").append(ru?"Вход из кэша: ":"Cached input: ").append(cached<0?"—":cached).append(" · ").append(cacheStatus).append("\n").append(ru?"Обработка входа / кэш / подготовка (мс): ":"Input / cache / setup (ms): ").append(prefillMs<0?"—":prefillMs).append(" / ").append(cacheMs<0?"—":cacheMs).append(" / ").append(setupMs<0?"—":setupMs).append("\n").append(ru?"После входа до первого токена (мс): ":"After input until first token (ms): ").append(firstStepMs<0?"—":firstStepMs).append("\n");s.append(ru?"Генераций в запросе: ":"Generations in request: ").append(genCalls).append("\n").append(ru?"До текста последней генерации: ":"Until last generation text: ").append(genCalls==0?"—":(genFirst<0?Math.max(0,now-genAt):genFirst-genAt)+" ms").append("\n");s.append(ru?"Последняя генерация: вход / выход (токены): ":"Last generation: input / output tokens: ").append(prompt<0?"—":prompt).append(" / ").append(tokens<0?"—":tokens).append("\n").append(ru?"Скорость последней генерации (примерно): ":"Last generation speed (approx): ").append(tokens>=0&&genDuration>0?String.format(Locale.ROOT,"%.1f",tokens*1000.0/genDuration)+" tok/s":"—").append("\n\n");s.append(passesReport(ru));for(String e:events){int colon=e.lastIndexOf(": ");s.append(label(colon<0?e:e.substring(0,colon),ru)).append(colon<0?"":e.substring(colon)).append('\n');}return s.toString();}
}
